.notification { position: relative; }.notification span { position: absolute; inset-block-start: 4px; inset-inline-end: 3px; width: 17px; height: 17px; display: grid; place-items: center; border-radius: 99px; color: white; background: var(--danger); font-size: 9px; }
[data-theme="dark"] .notification span { color: var(--page); }
.profile { display: flex; align-items: center; gap: 9px; padding-inline-start: 8px; }.avatar { width: 36px; height: 36px; display: grid; place-items: center; border-radius: 10px; color: var(--teal); background: var(--teal-soft); font-weight: 700; }

.page-actions, .toolbar-actions { display: flex; align-items: center; gap: 8px; row-gap: 10px; flex-wrap: wrap; }
.overview-commands { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
