.topbar { height: 64px; }.topbar-actions { gap: 0; }.global-search { display: none; }.page { padding: 20px 14px 40px; }.page-header h1 { font-size: 24px; }.page-actions .select { flex: 1; }
.page-actions .segmented-control button, .page-actions .date-presets button { min-height: 44px; }
.page-actions .button { max-width: 100%; white-space: normal; }
.overview-page .page-actions { width: 100%; }
.overview-commands { width: 100%; }
.overview-commands .button { flex: 1; }
.topbar .sign-out-button { min-width: 44px; padding-inline: 10px; }
.topbar .sign-out-button span { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
